#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk #:package Avalonia@11.3.10 #:package Avalonia.Desktop@11.3.10 #:package Avalonia.ReactiveUI@11.3.9 #:package Avalonia.Diagnostics@11.3.10 #:package Microsoft.Extensions.DependencyInjection@10.0.0 #:package Microsoft.Extensions.Hosting@10.0.0 #:package Microsoft.Extensions.Logging@10.0.0 #:package Microsoft.Extensions.Logging.Console@10.0.0 #:package Microsoft.Extensions.Logging.Debug@10.0.0 #:package ReactiveUI.Fody@19.1.1 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable #:property UseWPF=false #:property UseWinUI=false  using Avalonia; using Avalonia.Controls; using Avalonia.Controls.Primitives; using Avalonia.Controls.ApplicationLifetimes; using Avalonia.Data; using Avalonia.Layout; using Avalonia.ReactiveUI;  using ReactiveUI; using System; using System.Collections.Generic; using System.Linq; using System.Reactive; using System.Threading; using System.Threading.Tasks; using Avalonia.Styling;  namespace AvaloniaIntegration {     /// <summary>     /// Avalonia应用配置选项     /// </summary>     public class AvaloniaOptions     {         public string Title { get; set; } = "Avalonia Production App";         public int Width { get; set; } = 1024;         public int Height { get; set; } = 768;         public bool UseReactiveUI { get; set; } = true;         public ThemeVariant DefaultTheme { get; set; } = ThemeVariant.Light;         public bool EnableHotReload { get; set; } = true;         public bool EnableDevTools { get; set; } = true;         public bool EnableAotCompilation { get; set; } = false;         public bool EnableAccessibility { get; set; } = true;         public string[] PluginDirectories { get; set; } = Array.Empty<string>();     }      /// <summary>     /// Avalonia应用服务接口     /// </summary>     public interface IAvaloniaService     {         Task InitializeAsync(CancellationToken cancellationToken = default);         Task RunAsync(string[] args, CancellationToken cancellationToken = default);         void Run(string[] args);         void SetTheme(ThemeVariant theme);         ThemeVariant GetCurrentTheme();         Window CreateWindow();         void CloseWindow(Window window);         Task ShutdownAsync(CancellationToken cancellationToken = default);     }      /// <summary>     /// Avalonia应用服务实现     /// </summary>     public class AvaloniaService : IAvaloniaService     {         private readonly AvaloniaOptions _options;         private ThemeVariant _currentTheme;         private List<Window> _windows = new();          public AvaloniaService(AvaloniaOptions options)         {             _options = options;             _currentTheme = _options.DefaultTheme;         }          public async Task InitializeAsync(CancellationToken cancellationToken = default)         {             await Task.CompletedTask;         }          public void Run(string[] args)         {             Program.Main(args);         }          public async Task RunAsync(string[] args, CancellationToken cancellationToken = default)         {             await Task.Run(() => Program.Main(args), cancellationToken);         }          public void SetTheme(ThemeVariant theme)         {             _currentTheme = theme;             if (Application.Current is not null)             {                 Application.Current.RequestedThemeVariant = theme;             }         }          public ThemeVariant GetCurrentTheme()         {             if (Application.Current != null)             {                 return Application.Current.ActualThemeVariant;             }             return _currentTheme;         }          public Window CreateWindow()         {             var window = new MainWindow();             window.Width = _options.Width;             window.Height = _options.Height;             window.Title = _options.Title;             window.RequestedThemeVariant = _currentTheme;                          _windows.Add(window);             window.Closed += (sender, e) =>             {                 _windows.Remove(window);             };              return window;         }          public void CloseWindow(Window window)         {             if (_windows.Contains(window))             {                 window.Close();             }         }          public List<Window> GetWindows()         {             if (Application.Current?.ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop && desktop.Windows is not null)             {                 _windows = desktop.Windows.ToList();             }             return _windows;         }          public async Task ShutdownAsync(CancellationToken cancellationToken = default)         {             // 关闭所有窗口             foreach (var window in _windows.ToList())             {                 window.Close();             }              // 关闭应用程序             if (Application.Current?.ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop)             {                 desktop.Shutdown();             }              await Task.CompletedTask;         }     }      /// <summary>     /// 主应用程序类     /// </summary>     public class App : Application     {         public override void OnFrameworkInitializationCompleted()         {             if (ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop)             {                 desktop.MainWindow = new MainWindow();             }              base.OnFrameworkInitializationCompleted();         }     }      /// <summary>     /// 主窗口视图模型     /// </summary>     public class MainViewModel : ReactiveObject     {         private string _greeting = "Welcome to Avalonia Production App!";         private int _counter = 0;         private bool _isDarkTheme;          public string Greeting         {             get => _greeting;             set => this.RaiseAndSetIfChanged(ref _greeting, value);         }          public int Counter         {             get => _counter;             set => this.RaiseAndSetIfChanged(ref _counter, value);         }          public bool IsDarkTheme         {             get => _isDarkTheme;             set => this.RaiseAndSetIfChanged(ref _isDarkTheme, value);         }          public ReactiveCommand<Unit, Unit> IncrementCommand { get; }         public ReactiveCommand<Unit, Unit> DecrementCommand { get; }          public MainViewModel()         {             // 初始化命令             IncrementCommand = ReactiveCommand.Create(() =>             {                 Counter++;             });              DecrementCommand = ReactiveCommand.Create(() =>             {                 Counter--;             });              // 监听主题变化             this.WhenAnyValue(x => x.IsDarkTheme)                 .Subscribe(isDark =>                 {                     var theme = isDark ? ThemeVariant.Dark : ThemeVariant.Light;                     Application.Current?.RequestedThemeVariant = theme;                 });         }     }      /// <summary>     /// 主窗口     /// </summary>     public class MainWindow : ReactiveWindow<MainViewModel>     {         public MainWindow()         {             Width = 1024;             Height = 768;             Title = "Avalonia Production App";              // 设置视图模型             ViewModel = new MainViewModel();              // 初始化UI组件             InitializeComponent();         }          private void InitializeComponent()         {             // 创建UI组件（在实际应用中，这会从XAML文件加载）             var grid = new Grid             {                 ColumnDefinitions = new ColumnDefinitions("Auto, 1*, Auto"),                 RowDefinitions = new RowDefinitions("Auto, Auto, Auto, 1*"),                 Margin = new Thickness(20)             };              // 标题             var titleText = new TextBlock             {                 Text = "Avalonia Production App",                 FontSize = 24,                 FontWeight = Avalonia.Media.FontWeight.Bold,                 HorizontalAlignment = HorizontalAlignment.Center,                 Margin = new Thickness(0, 0, 0, 20)             };             Grid.SetColumn(titleText, 0);             Grid.SetColumnSpan(titleText, 3);             Grid.SetRow(titleText, 0);             grid.Children.Add(titleText);              // 问候语             var greetingText = new TextBlock             {                 HorizontalAlignment = HorizontalAlignment.Center,                 Margin = new Thickness(0, 0, 0, 20)             };             greetingText.Bind(TextBlock.TextProperty, new Binding("Greeting"));             Grid.SetColumn(greetingText, 0);             Grid.SetColumnSpan(greetingText, 3);             Grid.SetRow(greetingText, 1);             grid.Children.Add(greetingText);              // 计数器控件             var decrementButton = new Button             {                 Content = "-",                 Width = 40,                 Height = 40             };             if (ViewModel != null) decrementButton.Command = ViewModel.DecrementCommand;             Grid.SetColumn(decrementButton, 0);             Grid.SetRow(decrementButton, 2);             grid.Children.Add(decrementButton);              var counterText = new TextBlock             {                 HorizontalAlignment = HorizontalAlignment.Center,                 VerticalAlignment = VerticalAlignment.Center,                 FontSize = 18,                 Margin = new Thickness(10, 0)             };             counterText.Bind(TextBlock.TextProperty, new Binding("Counter"));             Grid.SetColumn(counterText, 1);             Grid.SetRow(counterText, 2);             grid.Children.Add(counterText);              var incrementButton = new Button             {                 Content = "+",                 Width = 40,                 Height = 40             };             if (ViewModel != null) incrementButton.Command = ViewModel.IncrementCommand;             Grid.SetColumn(incrementButton, 2);             Grid.SetRow(incrementButton, 2);             grid.Children.Add(incrementButton);              // 主题切换按钮             var themeToggleButton = new ToggleButton             {                 Content = "Dark Theme",                 HorizontalAlignment = HorizontalAlignment.Center,                 Margin = new Thickness(0, 20, 0, 0)             };             if (ViewModel != null) themeToggleButton.Bind(ToggleButton.IsCheckedProperty, new Binding("IsDarkTheme"));             Grid.SetColumn(themeToggleButton, 0);             Grid.SetColumnSpan(themeToggleButton, 3);             Grid.SetRow(themeToggleButton, 3);             grid.Children.Add(themeToggleButton);              // 设置内容             Content = grid;         }     }      /// <summary>     /// 配置Avalonia应用服务的扩展方法     /// </summary>     public static class AvaloniaExtensions     {         /// <summary>         /// 创建Avalonia应用服务实例         /// </summary>         /// <param name="configure">配置选项的委托</param>         /// <returns>Avalonia应用服务实例</returns>         public static IAvaloniaService CreateAvaloniaIntegration(             Action<AvaloniaOptions> configure = null)         {             var options = new AvaloniaOptions();             configure?.Invoke(options);             return new AvaloniaService(options);         }     }      /// <summary>     /// 程序入口类     /// </summary>     public static class Program     {         public static void Main(string[] args)         {             try             {                 // 直接使用Avalonia的API启动应用，与参考文件保持一致                 BuildAvaloniaApp()                     .StartWithClassicDesktopLifetime(args, ShutdownMode.OnLastWindowClose);             }             catch (Exception ex)             {                 Console.WriteLine($"An error occurred: {ex.Message}");                 Console.WriteLine(ex.StackTrace);                 Environment.Exit(1);             }         }          public static AppBuilder BuildAvaloniaApp()         {             return AppBuilder.Configure<App>()                 .UsePlatformDetect()                 .UseReactiveUI();         }     } }
